const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laJolla = ee.Geometry.Point([-117.27, 32.85]);
  const date2018 = ee.Date('2018-08-01');
  const date2017 = ee.Date('2017-08-01');

  // 2. Data Acquisition & Check
  const sst2018 = ee.ImageCollection('NOAA/CDR/OISST/V2_1')
    .filterDate(date2018, date2018.advance(1, 'day'))
    .filterBounds(laJolla)
    .select('sst');

  const sst2017 = ee.ImageCollection('NOAA/CDR/OISST/V2_1')
    .filterDate(date2017, date2017.advance(1, 'day'))
    .filterBounds(laJolla)
    .select('sst');

  const size2018 = await sst2018.size().getInfo();
  const size2017 = await sst2017.size().getInfo();

  console.log(`2018 Images: ${size2018}`);
  console.log(`2017 Images: ${size2017}`);

  if (size2018 === 0 || size2017 === 0) {
    console.log("Missing data for one or both years.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing & Calculation
  const img2018 = sst2018.first();
  const img2017 = sst2017.first();

  const stats2018 = await img2018.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: laJolla.buffer(5000),
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2017 = await img2017.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: laJolla.buffer(5000),
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const temp2018 = stats2018['sst_mean'];
  const temp2017 = stats2017['sst_mean'];
  const count2018 = stats2018['sst_count'];
  const count2017 = stats2017['sst_count'];

  console.log(`2018: ${temp2018}°C (Pixels: ${count2018})`);
  console.log(`2017: ${temp2017}°C (Pixels: ${count2017})`);

  // 4. Validation & Final Answer
  if (count2018 === 0 || count2017 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (temp2018 === null || temp2017 === null || 
      temp2018 < -5 || temp2018 > 40 || 
      temp2017 < -5 || temp2017 > 40) {
    console.log("Invalid temperature values.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (temp2018 > temp2017) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
